-- File: conduit/conduit/src/Data/Conduit/Internal/Conduit.hs
loop :: Monad m => SealedConduitT () i m () -> ConduitT a (i, a) m ()
loop src0 = await >>= maybe (return ()) go
      where
        go a = do
          (src1, mi) <- lift $ src0 $$++ await
          case mi of
            Nothing -> leftover a
            Just i  -> yield (i, a) >> loop src1
